ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT '';
ALTER TABLE tasks ADD COLUMN cancelled_at TEXT;
ALTER TABLE appointments ADD COLUMN notes TEXT NOT NULL DEFAULT '';
ALTER TABLE cases ADD COLUMN consultant_id INTEGER REFERENCES users(id);
ALTER TABLE invoices ADD COLUMN line_items TEXT NOT NULL DEFAULT '';
ALTER TABLE invoices ADD COLUMN subtotal_minor INTEGER NOT NULL DEFAULT 0;
ALTER TABLE invoices ADD COLUMN discount_minor INTEGER NOT NULL DEFAULT 0;
ALTER TABLE invoices ADD COLUMN tax_minor INTEGER NOT NULL DEFAULT 0;
UPDATE invoices SET subtotal_minor=amount_minor;
ALTER TABLE leads ADD COLUMN address_line1 TEXT NOT NULL DEFAULT '';
ALTER TABLE leads ADD COLUMN address_line2 TEXT NOT NULL DEFAULT '';
ALTER TABLE leads ADD COLUMN city TEXT NOT NULL DEFAULT '';
ALTER TABLE leads ADD COLUMN province TEXT NOT NULL DEFAULT '';
ALTER TABLE leads ADD COLUMN postal_code TEXT NOT NULL DEFAULT '';
ALTER TABLE leads ADD COLUMN address_country TEXT NOT NULL DEFAULT '';
ALTER TABLE clients ADD COLUMN address_line1 TEXT NOT NULL DEFAULT '';
ALTER TABLE clients ADD COLUMN address_line2 TEXT NOT NULL DEFAULT '';
ALTER TABLE clients ADD COLUMN city TEXT NOT NULL DEFAULT '';
ALTER TABLE clients ADD COLUMN province TEXT NOT NULL DEFAULT '';
ALTER TABLE clients ADD COLUMN postal_code TEXT NOT NULL DEFAULT '';
ALTER TABLE clients ADD COLUMN address_country TEXT NOT NULL DEFAULT '';
CREATE TABLE client_messages (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 client_id INTEGER NOT NULL REFERENCES clients(id),
 case_id INTEGER REFERENCES cases(id),
 title TEXT NOT NULL,
 body TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Published','Withdrawn')),
 created_by INTEGER NOT NULL REFERENCES users(id),
 approved_by INTEGER REFERENCES users(id),
 published_at TEXT,
 created_at TEXT NOT NULL DEFAULT(datetime('now')),
 revision INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX client_messages_scope ON client_messages(client_id,case_id,id);
CREATE TABLE business_events (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 entity TEXT NOT NULL,
 record_id INTEGER NOT NULL,
 operation TEXT NOT NULL,
 actor_id INTEGER,
 before_state TEXT,
 after_state TEXT,
 created_at TEXT NOT NULL DEFAULT(datetime('now'))
);
CREATE INDEX business_events_record ON business_events(entity,record_id,id);
CREATE TRIGGER business_events_no_update BEFORE UPDATE ON business_events BEGIN SELECT RAISE(ABORT,'Business events are append-only'); END;
CREATE TRIGGER business_events_no_delete BEFORE DELETE ON business_events BEGIN SELECT RAISE(ABORT,'Business events are append-only'); END;
CREATE TRIGGER invoice_components_locked BEFORE UPDATE ON invoices WHEN OLD.status<>'Draft' AND (NEW.line_items IS NOT OLD.line_items OR NEW.subtotal_minor IS NOT OLD.subtotal_minor OR NEW.discount_minor IS NOT OLD.discount_minor OR NEW.tax_minor IS NOT OLD.tax_minor) BEGIN SELECT RAISE(ABORT,'Issued invoice components are immutable'); END;
CREATE TRIGGER payment_application_progress AFTER INSERT ON invoice_payments WHEN NEW.amount_minor>0 BEGIN
 UPDATE cases SET stage='Document Collection' WHERE stage='Awaiting Payment' AND id IN (SELECT case_id FROM invoice_balances WHERE id=NEW.invoice_id AND balance_minor=0);
END;
CREATE TRIGGER conversion_address AFTER UPDATE OF converted_client_id ON leads WHEN OLD.converted_client_id IS NULL AND NEW.converted_client_id IS NOT NULL BEGIN
 UPDATE clients SET address_line1=NEW.address_line1,address_line2=NEW.address_line2,city=NEW.city,province=NEW.province,postal_code=NEW.postal_code,address_country=NEW.address_country WHERE id=NEW.converted_client_id;
END;
